bool checkUserPasswordAgainstOwner(std::string& user_password, const std::string& owner_password, const QPDF::EncryptionData& data) {
    std::string o_data = data.getO();
    if (o_data.empty()) {
        return false;
    }

    std::string combined = user_password + owner_password;
    std::string rc4_key = computeRC4Key(combined, data.getKeyLength());

    std::string derived_password = rc4_encrypt(user_password, rc4_key);
    for (int i = 0; i < 19; ++i) {
        derived_password = rc4_encrypt(derived_password, rc4_key);
    }

    if (derived_password == o_data) {
        user_password = derived_password;
        return true;
    }

    return false;
}
